  | InvertAdjustment
  | LevelsAdjustment
  | HueSaturationAdjustment
  | PosterizeAdjustment
  | ThresholdAdjustment;

export interface AdjustmentLayer extends LayerBase {
  readonly kind: 'adjustment';
  readonly adjustment: Adjustment;
