function validateLayers(
  layers: readonly Layer[],
  ids = new Set<string>(),
  smartObjectDepth = 0,
): void {
  for (const layer of layers) {
    assertName(layer.id, 'Layer id');
    assertName(layer.name, 'Layer name');
