import type { Adjustment, SmartFilter } from '@freetoshop/core-document';
import type { FilterDraft, FilterKind } from './filterOperations.js';

export type ImageAdjustmentKind =
  | 'contrast'
  | 'levels'
  | 'hue-saturation'
  | 'grayscale'
  | 'invert'
  | 'threshold'
