export const IMAGE_ADJUSTMENT_COMMAND_IDS = IMAGE_ADJUSTMENT_DEFINITIONS.map(({ id }) => id);
export const FILTER_OPERATION_COMMAND_IDS = FILTER_MENU_DEFINITIONS.map(({ id }) => id);
