export function setLayerLock(
  id: LayerId,
  lock: keyof LayerLocks,
  enabled: boolean,
): DocumentTransform {
  return command('Set layer lock', (document) =>
    withLayers(
      document,
      mapLayer(document.layers, id, (layer) => ({
        ...layer,
        locks: { ...layer.locks, [lock]: enabled },
      })),
