        width: document.canvas.width,
        height: document.canvas.height,
        pixels: documentPixels(document),
      });
      const name =
        document.name.replace(/\.[^.]+$/, '').replace(/[^a-z0-9-_]+/gi, '-') || 'artwork';
      downloadBlob(blob, `${name}.png`);
      notify('PNG export completed.');
    } catch (error) {
