      if (!raster) throw new Error('Create a nonempty selection before exporting it.');
      const blob = await exportImage(raster);
      const name =
        document.name.replace(/\.[^.]+$/, '').replace(/[^a-z0-9-_]+/gi, '-') || 'artwork';
