      const name =
        document.name
          .replace(/\.[^.]+$/, '')
          .replace(/[^a-z0-9-_]+/gi, '-')
          .replace(/^-+|-+$/g, '') || 'artwork';
      downloadBlob(
        new Blob([result.buffer], { type: NATIVE_DOCUMENT_MIME_TYPE }),
        `${name}${NATIVE_DOCUMENT_EXTENSION}`,
