  setLayerEffects,
  setLayerLock,
  setAdjustmentLayerParameters,
  setLayerMaskDensity,
  setLayerMaskEnabled,
  setLayerRasterMask,
  setLayerVectorMask,
  setLayerVectorMaskDensity,
  setLayerVectorMaskEnabled,
  setLayerTranslation,
  setLayerTransform,
  setLayerVisibility,
  setShapeGeometry,
  setShapeStyle,
  setSmartObjectFilters,
  setSelection,
  selectAll,
  setTextContent,
  setTextStyle,
  transformPoint,
  ungroupLayer,
  type ImageDocument,
  BLEND_MODES,
  type Adjustment,
  type Layer,
  type LayerEffect,
  type LayerTransform,
  type PathCommand,
  type PixelLayer,
  type SmartFilter,
  type SelectionCombineMode,
  type SelectionMask,
} from '@freetoshop/core-document';
import { CommandHistory } from '@freetoshop/command-history';
import type { PixelRegion } from '@freetoshop/pixel-storage';
import { exportImage, importImageDocument } from '@freetoshop/file-codecs';
import { hasPsdSignature, PSD_MIME_TYPE } from '@freetoshop/file-codecs/signatures';
import {
