  const [imageSizeDraft, setImageSizeDraft] = useState<ImageSizeDraft>({
    width: '',
    height: '',
    method: 'bilinear',
    constrain: true,
  });
  const [filterDraft, setFilterDraft] = useState<FilterDraft>({
    kind: 'contrast',
    contrast: 20,
    inputBlack: 0,
    gamma: 1,
    inputWhite: 255,
    outputBlack: 0,
    outputWhite: 255,
    hue: 0,
    saturation: 20,
    lightness: 0,
    threshold: 128,
    posterizeLevels: 4,
    blurRadius: 2,
