          type: 'stroke',
          enabled: true,
          opacity: 1,
          size: 4,
          color: { red: 255, green: 255, blue: 255, alpha: 255 },
        },
        'drop-shadow': {
          type: 'drop-shadow',
          enabled: true,
          opacity: 0.6,
          offsetX: 8,
          offsetY: 8,
          blur: 6,
          color: { red: 0, green: 0, blue: 0, alpha: 255 },
        },
