  const selectWithMagicWand = useCallback(
    (point: DocumentPoint) => {
      if (!document) return;
      const seedX = Math.floor(point.x);
      const seedY = Math.floor(point.y);
      if (
        seedX < 0 ||
        seedY < 0 ||
        seedX >= document.canvas.width ||
        seedY >= document.canvas.height
