    })),
    {
      id: 'image.size',
      label: 'Image Size…',
      menu: 'image',
      shortcut: 'Ctrl+Alt+I',
      enabled: Boolean(document) && !busy,
      execute: () => openImageSize(),
    },
    {
      id: 'image.canvas-size',
      label: 'Canvas Size…',
      menu: 'image',
      shortcut: 'Ctrl+Alt+C',
      enabled: Boolean(document) && !busy,
      execute: () => openCanvasSize(),
    },
    {
      id: 'image.reveal-all',
      label: 'Reveal All',
      menu: 'image',
      enabled: Boolean(document) && !busy,
      execute: revealEntireDocument,
    },
    {
      id: 'layer.new',
      label: 'New Layer',
      menu: 'layer',
      order: 10,
      shortcut: 'Ctrl+Shift+N',
