      .store.write({ x: 30, y: 30, width: 2, height: 2, pixels }).store;
    expect(resampleCoverageStore(coverage, 19, 17, 'bilinear').toContiguous()).toEqual(
      resampleCoverage(coverage.toContiguous(), 32, 32, 19, 17, 'bilinear'),
