  it('replicates exact nearest-neighbor quadrants when enlarging', () => {
    const source = [255, 0, 0, 255, 0, 255, 0, 255, 0, 0, 255, 255, 255, 255, 0, 255];
    const resized = resamplePixels(source, 2, 2, 4, 4, 'nearest');
