        { type: 'line', x: 2, y: 2.25 },
        { type: 'close' },
      ],
    });
    expect(findLayer(resized, 'adjustment')).toMatchObject({
      kind: 'adjustment',
      vectorMask: {
        width: 8,
        height: 6,
        commands: [
          { type: 'move', x: 2, y: 1.5 },
          { type: 'line', x: 6, y: 1.5 },
          { type: 'line', x: 4, y: 4.5 },
