export interface CloneSource {
  /** Source document that owns the source layer. */
  readonly sourceDocument: ImageDocument;
  /** Source layer to sample pixels from. */
  readonly sourceLayer: PixelLayer;
  /** Document-space point on the source layer where sampling originates. */
  readonly sourceDocumentPoint: DocumentPoint;
  /** Whether the source-to-destination offset is preserved across the gesture. */
  readonly aligned: boolean;
}

/** Source-space sample coordinates for a clone stamp stroke. */
interface CloneSample {
  /** Source layer local-space x coordinate. */
  readonly x: number;
  /** Source layer local-space y coordinate. */
  readonly y: number;
}

export interface CloneStampOptions {
  /** Diameter in document pixels. */
  readonly size: number;
  /** Normalized hard-core radius. */
  readonly hardness: number;
  readonly opacity: number;
  readonly source: CloneSource;
}

/**
 * Paints a deterministic clone-stamp stroke that samples pixels from a source
 * layer and writes them into a destination layer. Returns the smallest
 * destination-layer-local patch containing changed pixels, or a 0×0 patch when
 * nothing changes.
 *
 * Document-space semantics:
 * - `source.sourceDocumentPoint` is a point in the source document.
 * - `points` are document-space points on the destination layer.
 * - `worldTransform` maps destination-local coordinates to destination document
 *   coordinates.
 * - In aligned mode the source-document offset between the source point and each
 *   destination point is preserved; in unaligned mode every dab samples back from
 *   `sourceDocumentPoint`.
 *
 * The operation respects the active selection (clipped to document space) and
 * uses the existing brush falloff/opacity pipeline.
 */
export function cloneStampStroke(
  destinationLayer: PixelLayer,
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
  worldTransform: LayerTransform = destinationLayer.transform,
): PixelPatch {
  validateLayer(destinationLayer);
  validateTransform(worldTransform);
  validateSelection(selection);
  if (points.length === 0) throw new RangeError('Stroke must contain at least one point');
  assertFinite(options.size, 'Clone brush size');
  if (options.size <= 0) throw new RangeError('Clone brush size must be greater than 0');
  assertUnit(options.hardness, 'Clone brush hardness');
  assertUnit(options.opacity, 'Clone brush opacity');
  if (!options.source.sourceLayer) throw new RangeError('Clone source layer is missing');
  if (options.source.sourceLayer.pixelStore.width !== options.source.sourceLayer.width ||
      options.source.sourceLayer.pixelStore.height !== options.source.sourceLayer.height) {
    throw new RangeError('Clone source layer pixel store does not match its dimensions');
  }
  for (const [index, point] of points.entries()) {
    assertFinite(point.x, `Stroke point ${String(index)} x`);
    assertFinite(point.y, `Stroke point ${String(index)} y`);
    assertUnit(point.pressure ?? 1, `Stroke point ${String(index)} pressure`);
  }

  const radius = options.size / 2;
  const inverse = invertTransform(worldTransform);
  const sourceTransform = options.source.sourceLayer.transform;
  const inverseSource = invertTransform(sourceTransform);
  const spacing = Math.max(0.25, radius * 0.5);

  // Expand dab list with interpolated points.
  const dabs: Array<{ x: number; y: number; pressure: number }> = [];
  const first = points[0];
  dabs.push({ x: first.x, y: first.y, pressure: first.pressure ?? 1 });
  for (let index = 1; index < points.length; index += 1) {
    const start = points[index - 1];
    const end = points[index];
    const distance = Math.hypot(end.x - start.x, end.y - start.y);
    const steps = Math.max(1, Math.ceil(distance / spacing));
    for (let step = 1; step <= steps; step += 1) {
      const progress = step / steps;
      dabs.push({
        x: start.x + (end.x - start.x) * progress,
        y: start.y + (end.y - start.y) * progress,
        pressure: (start.pressure ?? 1) + ((end.pressure ?? 1) - (start.pressure ?? 1)) * progress,
      });
    }
  }

  // Compute source-document-space offset for aligned mode.
  const sourceDocumentOffset: DocumentPoint | null =
    options.source.aligned
      ? { x: dabs[0].x - options.source.sourceDocumentPoint.x,
          y: dabs[0].y - options.source.sourceDocumentPoint.y }
      : null;

  // Destination working set: union of local dab bounds only (no full-layer densify).
  let strokeBounds: Bounds | null = null;
  for (const dab of dabs) {
    strokeBounds = unionBounds(
      strokeBounds,
      localDabBounds(worldTransform, inverse, dab.x, dab.y, radius, destinationLayer.width, destinationLayer.height),
    );
  }
  if (strokeBounds === null || strokeBounds.right < strokeBounds.left) {
    return emptyPatch();
  }

  const regionLeft = strokeBounds.left;
  const regionTop = strokeBounds.top;
  const regionWidth = strokeBounds.right - strokeBounds.left + 1;
  const regionHeight = strokeBounds.bottom - strokeBounds.top + 1;
  const next = destinationLayer.pixelStore.read({
    x: regionLeft,
    y: regionTop,
    width: regionWidth,
    height: regionHeight,
  });
  const selectionRegion = readSelectionRegion(selection, dabs, radius);
  let changedBounds: Bounds | null = null;

  for (const dab of dabs) {
    const bounds = localDabBounds(
      worldTransform,
      inverse,
      dab.x,
      dab.y,
      radius,
      destinationLayer.width,
      destinationLayer.height,
    );
    const { left, top, right, bottom } = bounds;
    for (let y = top; y <= bottom; y += 1) {
      for (let x = left; x <= right; x += 1) {
        const documentPoint = transformPoint(worldTransform, x, y);
        const falloff = dabCoverage(
          Math.hypot(documentPoint.x - dab.x, documentPoint.y - dab.y),
          radius,
          options.hardness,
        );
        const selected = selectionCoverage(
          selection,
          documentPoint.x,
          documentPoint.y,
          selectionRegion.buffer,
          selectionRegion.region,
        );
        const coverage = falloff * options.opacity * dab.pressure * selected;
        if (coverage <= 0) continue;

        // Determine source document-space sample point.
        let sourceDocumentX: number;
        let sourceDocumentY: number;
        if (sourceDocumentOffset !== null) {
          sourceDocumentX = documentPoint.x - sourceDocumentOffset.x + options.source.sourceDocumentPoint.x;
          sourceDocumentY = documentPoint.y - sourceDocumentOffset.y + options.source.sourceDocumentPoint.y;
        } else {
          sourceDocumentX = options.source.sourceDocumentPoint.x;
          sourceDocumentY = options.source.sourceDocumentPoint.y;
        }

        // Transform to source layer local space.
        const sourceLocal = transformPoint(inverseSource, sourceDocumentX, sourceDocumentY);

        // Bounds-check before reading from source layer.
        if (
          sourceLocal.x < 0 || sourceLocal.y < 0 ||
          sourceLocal.x >= options.source.sourceLayer.width ||
          sourceLocal.y >= options.source.sourceLayer.height
        ) {
          continue;
        }

        // Read a single source pixel via the tiled store (bounded read).
        const sourcePixel = options.source.sourceLayer.pixelStore.read({
          x: Math.floor(sourceLocal.x),
          y: Math.floor(sourceLocal.y),
          width: 1,
          height: 1,
        });

        const offset = ((y - regionTop) * regionWidth + (x - regionLeft)) * 4;
        const before = [next[offset], next[offset + 1], next[offset + 2], next[offset + 3]];
        compositeSourceOver(next, offset, [
          sourcePixel[0],
          sourcePixel[1],
          sourcePixel[2],
          sourcePixel[3],
        ], coverage);
        if (
          before[0] !== next[offset] ||
          before[1] !== next[offset + 1] ||
          before[2] !== next[offset + 2] ||
          before[3] !== next[offset + 3]
        ) {
          changedBounds = include(changedBounds, x, y);
        }
      }
    }
  }

  return makePatchFromRegion(regionLeft, regionTop, regionWidth, next, changedBounds);
}

/**
 * Sets the clone source document and layer, returning a data model suitable for
exposing source state to the UI and tests.
 */
export function createCloneSource(
  sourceDocument: ImageDocument,
  sourceLayerId: string,
  sourceDocumentPoint: DocumentPoint,
  aligned: boolean = true,
): CloneSource {
  const sourceLayer = findLayer(sourceDocument, sourceLayerId);
  if (!sourceLayer || sourceLayer.kind !== 'pixel') {
    throw new RangeError('Clone source layer must be a pixel layer');
  }
  return {
    sourceDocument,
    sourceLayer: sourceLayer as PixelLayer,
    sourceDocumentPoint,
    aligned,
  };
}

