+ 170   const regionWidth = strokeBounds.right - strokeBounds.left + 1;
+ 171   const regionHeight = strokeBounds.bottom - strokeBounds.top + 1;
+ 172   const next = destinationLayer.pixelStore.read({
+ 173     x: regionLeft,
+ 174     y: regionTop,
+ 175     width: regionWidth,
+ 176     height: regionHeight,
+ 177   });
+ 178   const selectionRegion = readSelectionRegion(selection, dabs, radius);
+ 179   let changedBounds: Bounds | null = null;
+ 180 
+ 181   for (const dab of dabs) {
+ 182     const bounds = localDabBounds(
+ 183       worldTransform,
+ 184       inverse,
+ 185       dab.x,
+ 186       dab.y,
+ 187       radius,
+ 188       destinationLayer.width,
+ 189       destinationLayer.height,
+ 190     );
+ 191     const { left, top, right, bottom } = bounds;
+ 192     for (let y = top; y <= bottom; y += 1) {
+ 193       for (let x = left; x <= right; x += 1) {
+ 194         const documentPoint = transformPoint(worldTransform, x, y);
+ 195         const falloff = dabCoverage(
+ 196           Math.hypot(documentPoint.x - dab.x, documentPoint.y - dab.y),
+ 197           radius,
+ 198           options.hardness,
+ 199         );
+ 200         const selected = selectionCoverage(
+ 201           selection,
+ 202           documentPoint.x,
+ 203           documentPoint.y,
+ 204           selectionRegion.buffer,
+ 205           selectionRegion.region,
+ 206         );
