+ 211         let sourceDocumentX: number;
+ 212         let sourceDocumentY: number;
+ 213         if (sourceDocumentOffset !== null) {
+ 214           sourceDocumentX = documentPoint.x - sourceDocumentOffset.x + options.source.sourceDocumentPoint.x;
