+ 255           changedBounds = include(changedBounds, x, y);
+ 256         }
+ 257       }
+ 258     }
+ 259   }
+ 260 
+ 261   return makePatchFromRegion(regionLeft, regionTop, regionWidth, next, changedBounds);
+ 262 }
