  ImageSizeDraft,
  PathHandleRole,
  SmartObjectEditSession,
  Toast,
  Tool,
  TransformDraft,
} from './editor/types.js';
import {
  MAX_DOCUMENT_DIMENSION,
  colorToHex,
  createBlankDocument,
  displayLayers,
  flattenLayers,
  freeTransformAtPoint,
  hexColor,
  hexToColor,
