import { TiledCoverageStore, TiledPixelStore } from '@freetoshop/pixel-storage';

export type LayerId = string;

export interface LayerTransform {
  readonly a: number;
  readonly b: number;
  readonly c: number;
  readonly d: number;
  readonly e: number;
  readonly f: number;
}

export interface TransformPoint {
  readonly x: number;
  readonly y: number;
}

export const BLEND_MODES = [
  'normal',
  'multiply',
  'screen',
  'overlay',
  'darken',
  'darker-color',
  'lighten',
  'lighter-color',
  'color-dodge',
  'linear-dodge',
  'color-burn',
  'linear-burn',
  'hard-light',
  'soft-light',
  'vivid-light',
  'linear-light',
  'pin-light',
  'hard-mix',
  'difference',
  'exclusion',
  'subtract',
  'divide',
  'hue',
  'saturation',
  'color',
  'luminosity',
] as const;

export type BlendMode = (typeof BLEND_MODES)[number];
export type GroupCompositingMode = 'pass-through' | 'isolated';

export interface LayerLocks {
  readonly transparency: boolean;
  readonly pixels: boolean;
  readonly position: boolean;
  readonly all: boolean;
}

export interface ColorOverlayEffect {
  readonly type: 'color-overlay';
  readonly enabled: boolean;
  readonly opacity: number;
  readonly blendMode: BlendMode;
  readonly color: RgbaColor;
}

export interface StrokeEffect {
  readonly type: 'stroke';
  readonly enabled: boolean;
  readonly opacity: number;
  readonly size: number;
  readonly color: RgbaColor;
}

export interface DropShadowEffect {
  readonly type: 'drop-shadow';
  readonly enabled: boolean;
  readonly opacity: number;
  readonly offsetX: number;
  readonly offsetY: number;
  readonly blur: number;
  readonly color: RgbaColor;
}

export type LayerEffect = ColorOverlayEffect | StrokeEffect | DropShadowEffect;

export interface LayerBase {
  readonly id: LayerId;
  readonly name: string;
  readonly visible: boolean;
  readonly opacity: number;
  readonly fillOpacity: number;
  readonly blendMode: BlendMode;
  readonly clipping: boolean;
  readonly locks: LayerLocks;
  readonly transform: LayerTransform;
