export interface SmartObjectSource {
  readonly id: string;
  readonly name: string;
  readonly canvas: DocumentCanvas;
  readonly layers: readonly Layer[];
}

interface SmartFilterBase {
  readonly id: string;
  readonly enabled: boolean;
