  useEffect(() => {
    setVectorMaskDensityDraft(Math.round((selectedVectorMask?.density ?? 1) * 100));
  }, [selectedLayerId, selectedVectorMask?.density]);

  useEffect(() => {
    setChannelNameDraft(selectedChannel?.name ?? '');
