  useEffect(() => {
    setLayerTransformDraft(transformDraft(selectedLayer?.transform ?? identityLayerTransform()));
  }, [selectedLayer?.id, selectedLayer?.transform]);

  useEffect(() => {
    if (!activePixelOperation) {
      setFilterError(null);
      setPreviewDocument(null);
