          setRevision((value) => value + 1);
        }
        notify(`${family} loaded locally with professional OpenType shaping.`);
      } catch (error) {
        notify(error instanceof Error ? error.message : 'The font could not be loaded.', 'error');
      } finally {
        setBusy(false);
