      const deltaY = event.key === 'ArrowUp' ? -step : event.key === 'ArrowDown' ? step : 0;
      try {
        const next = scaleTransformFromHandle(
          transformOverlay.snapshot,
          handle,
          {
            x: geometry.x + deltaX / viewport.zoom,
            y: geometry.y + deltaY / viewport.zoom,
