        context.strokeStyle = '#17b897';
        context.stroke();
        const anchorSize = 7 / viewport.zoom;
        context.fillStyle = '#e7fffa';
        context.strokeStyle = '#07110f';
        context.lineWidth = 1 / viewport.zoom;
