          <PanelContent id="properties">
            <>
              {selectedLayer && (
                <LayerPropertiesSections
                  {...{
                    addAdjustmentMask,
                    addLayerEffect,
                    addLayerMaskFromSelection,
                    addHideAllMask,
                    addRectangularVectorMask,
                    addRevealAllMask,
                    addSmartFilter,
