    expect(resizedEmpty.tileCount).toBe(0);
    expect(resizedEmpty.width).toBe(32);
    expect(resizedEmpty.height).toBe(32);

    const sparse = TiledCoverageStore.empty(64, 64).write({
      x: 8,
      y: 8,
